/** R7-P0-08 Calibrated session key limits. */
export const CALIBRATED_LIMITS = {
    /** Session key daily cap: 50 FLOP (in planck, 18 decimals). */
    dailyCap: 50n * 10n ** 18n,
    /** Session key per-tx limit: 5 FLOP (in planck, 18 decimals). */
    perTxLimit: 5n * 10n ** 18n,
    /** Circuit breaker period: 60 blocks. */
    circuitBreakerPeriod: 60,
    /** Circuit breaker max txs per period. */
    circuitBreakerMaxTxs: 100,
    /** Circuit breaker max spend per period: 250 FLOP. */
    circuitBreakerMaxSpend: 250n * 10n ** 18n,
    /** Max session rotations per hour. */
    maxRotationsPerHour: 3,
};
